// Verification de signature Wave (HMAC) avant tout traitement.
// A adapter selon le mecanisme de signature exact documente par Wave.
const crypto = require('crypto');
const body = $input.first().json.body;
const headers = $input.first().json.headers;

const signature = headers['wave-signature'] || headers['x-wave-signature'];
const secret = $env.WAVE_WEBHOOK_SECRET;

if (!signature || !secret) {
  return [{ json: { error: true, provider: 'wave', message: 'Signature ou secret manquant, rejet par precaution.' } }];
}

const computedSignature = crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex');

if (computedSignature !== signature) {
  return [{ json: { error: true, provider: 'wave', message: 'Signature invalide, webhook potentiellement frauduleux rejete.' } }];
}

return [{
  json: {
    error: false,
    provider: 'wave',
    transactionId: body.id || body.transaction_id,
    orderReference: body.client_reference || body.metadata?.orderId,
    status: body.checkout_status || body.status,
    amount: body.amount,
    customerWhatsapp: body.metadata?.customerWhatsapp
  }
}];

// Verification de signature Orange Money avant tout traitement.
// A adapter selon le mecanisme de signature exact documente par Orange Money Senegal.
const crypto = require('crypto');
const body = $input.first().json.body;
const headers = $input.first().json.headers;

const signature = headers['om-signature'] || headers['x-om-signature'];
const secret = $env.ORANGE_MONEY_WEBHOOK_SECRET;

if (!signature || !secret) {
  return [{ json: { error: true, provider: 'orange_money', message: 'Signature ou secret manquant, rejet par precaution.' } }];
}

const computedSignature = crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex');

if (computedSignature !== signature) {
  return [{ json: { error: true, provider: 'orange_money', message: 'Signature invalide, webhook potentiellement frauduleux rejete.' } }];
}

return [{
  json: {
    error: false,
    provider: 'orange_money',
    transactionId: body.transactionId || body.txnid,
    orderReference: body.order_id || body.reference,
    status: body.status,
    amount: body.amount,
    customerWhatsapp: body.customerWhatsapp
  }
}];

// Idempotence cross-provider : un meme transactionId ne doit jamais etre traite deux fois.
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedTransactionIds) staticData.processedTransactionIds = [];

const txId = $json.provider + ':' + $json.transactionId;

if (staticData.processedTransactionIds.includes(txId)) {
  return [{ json: { ...$json, skip: true, message: 'Transaction deja traitee (doublon webhook)' } }];
}

staticData.processedTransactionIds.push(txId);
if (staticData.processedTransactionIds.length > 1000) {
  staticData.processedTransactionIds = staticData.processedTransactionIds.slice(-1000);
}

return [{ json: { ...$json, skip: false } }];

// Normalise les statuts heterogenes des deux providers vers un statut interne unique
const raw = ($json.status || '').toLowerCase();

let normalizedStatus;
if (['success', 'succeeded', 'completed', 'paid'].includes(raw)) {
  normalizedStatus = 'paye';
} else if (['failed', 'cancelled', 'canceled', 'declined'].includes(raw)) {
  normalizedStatus = 'echec';
} else if (['pending', 'processing'].includes(raw)) {
  normalizedStatus = 'en_attente';
} else {
  normalizedStatus = 'inconnu';
}

return [{
  json: {
    ...$json,
    normalizedStatus
  }
}];

// Construit le message de confirmation client apres paiement reussi
const order = $('Normaliser statut paiement').first().json;
return [{
  json: {
    messaging_product: 'whatsapp',
    to: order.customerWhatsapp,
    type: 'text',
    text: { body: 'Paiement recu avec succes ! Votre commande ' + (order.orderReference || '') + ' est confirmee et va etre preparee. Merci de votre confiance.' }
  }
}];
